LOCK TABLES `eom_posts` WRITE;
/*!40000 ALTER TABLE `eom_posts` DISABLE KEYS */;
INSERT INTO `eom_posts` VALUES (1,1,'2025-05-22 22:27:05','2025-05-22 22:27:05','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2025-05-22 22:27:05','2025-05-22 22:27:05','',0,'http://box4237/cgi/addon_GT.cgi?s=GT::WP::Install::Cpanel+%28hqqiksmy%29+-+127.0.0.1+%5Bnocaller%5D/?p=1',0,'post','',1),(2,1,'2025-05-22 22:27:05','2025-05-22 22:27:05','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\"><p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p></blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://box4237/cgi/addon_GT.cgi?s=GT::WP::Install::Cpanel+%28hqqiksmy%29+-+127.0.0.1+%5Bnocaller%5D/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2025-05-22 22:27:05','2025-05-22 22:27:05','',0,'http://box4237/cgi/addon_GT.cgi?s=GT::WP::Install::Cpanel+%28hqqiksmy%29+-+127.0.0.1+%5Bnocaller%5D/?page_id=2',0,'page','',0),(4,1,'2025-05-23 15:01:37','2025-05-23 15:01:37','{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }','Custom Styles','','publish','closed','closed','','wp-global-styles-twentytwentyfive','','','2025-05-23 15:01:37','2025-05-23 15:01:37','',0,'http://localhost/Ggani_Foundation/wp-global-styles-twentytwentyfive/',0,'wp_global_styles','',0),(5,1,'2025-05-23 15:02:19','2025-05-23 15:02:19','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2025-05-23 15:02:19','2025-05-23 15:02:19','',0,'http://localhost/Ggani_Foundation/navigation/',0,'wp_navigation','',0),(6,1,'2025-05-23 15:05:30','2025-05-23 15:05:30','{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }','Custom Styles','','publish','closed','closed','','wp-global-styles-astra','','','2025-05-23 15:05:30','2025-05-23 15:05:30','',0,'http://localhost/Ggani_Foundation/wp-global-styles-astra/',0,'wp_global_styles','',0),(7,1,'2025-05-23 15:16:06','2025-05-23 15:16:06','','IMG-20250518-WA0019','','inherit','open','closed','','img-20250518-wa0019','','','2025-05-23 15:16:06','2025-05-23 15:16:06','',0,'http://localhost/Ggani_Foundation/wp-content/uploads/2025/05/IMG-20250518-WA0019.jpg',0,'attachment','image/jpeg',0),(8,1,'2025-05-23 15:16:08','2025-05-23 15:16:08','','IMG-20250518-WA0020','','inherit','open','closed','','img-20250518-wa0020','','','2025-05-23 15:16:08','2025-05-23 15:16:08','',0,'http://localhost/Ggani_Foundation/wp-content/uploads/2025/05/IMG-20250518-WA0020.jpg',0,'attachment','image/jpeg',0),(9,1,'2025-05-23 15:16:11','2025-05-23 15:16:11','','IMG-20250518-WA0021','','inherit','open','closed','','img-20250518-wa0021','','','2025-05-23 15:16:11','2025-05-23 15:16:11','',0,'http://localhost/Ggani_Foundation/wp-content/uploads/2025/05/IMG-20250518-WA0021.jpg',0,'attachment','image/jpeg',0),(10,1,'2025-05-23 15:16:13','2025-05-23 15:16:13','','IMG-