<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"8fed953a\",\"widthDesktop\":33,\"justifyContentDesktop\":\"flex-start\",\"backgroundType\":\"color\",\"backgroundColor\":\"var(u002du002dast-global-color-5)\",\"topPaddingDesktop\":40,\"bottomPaddingDesktop\":40,\"leftPaddingDesktop\":40,\"rightPaddingDesktop\":40,\"topPaddingTablet\":24,\"bottomPaddingTablet\":24,\"leftPaddingTablet\":24,\"rightPaddingTablet\":24,\"topPaddingMobile\":24,\"bottomPaddingMobile\":24,\"leftPaddingMobile\":24,\"rightPaddingMobile\":24,\"widthSetByUser\":true,\"containerBorderTopLeftRadius\":0,\"containerBorderTopRightRadius\":30,\"containerBorderBottomLeftRadius\":30,\"containerBorderBottomRightRadius\":0,\"containerBorderRadiusLink\":false,\"isGridCssInParent\":true} -->\n<div class=\"wp-block-uagb-container uagb-block-8fed953a\"><!-- wp:uagb/advanced-heading {\"block_id\":\"964dee5b\",\"classMigrate\":true,\"headingDescToggle\":true,\"subHeadingColor\":\"\",\"headingTag\":\"h3\",\"headSpace\":17,\"headSpaceMobile\":8,\"headSpaceTablet\":8,\"subHeadSpace\":0,\"subHeadSpaceMobile\":0} -->\n<div class=\"wp-block-uagb-advanced-heading uagb-block-964dee5b\"><h3 class=\"uagb-heading-text\">Community Engagement</h3><p class=\"uagb-desc-text\">We build strong communities by bringing together children and families, fostering connections through the love of tennis.</p></div>\n<!-- /wp:uagb/advanced-heading --></div>\n<!-- /wp:uagb/container -->\n\n<!-- wp:uagb/container {\"block_id\":\"b1e555fe\",\"widthDesktop\":33,\"justifyContentDesktop\":\"flex-start\",\"backgroundType\":\"color\",\"backgroundColor\":\"var(u002du002dast-global-color-5)\",\"topPaddingDesktop\":40,\"bottomPaddingDesktop\":40,\"leftPaddingDesktop\":40,\"rightPaddingDesktop\":40,\"topPaddingTablet\":24,\"bottomPaddingTablet\":24,\"leftPaddingTablet\":24,\"rightPaddingTablet\":24,\"topPaddingMobile\":24,\"bottomPaddingMobile\":24,\"leftPaddingMobile\":24,\"rightPaddingMobile\":24,\"widthSetByUser\":true,\"cont